package main

import (
	"errors"
	"io"
	"sync"
	"time"

	"golang.org/x/net/context"

	"github.com/jacobsa/fuse/fuseops"
)

type cacheKey struct {
	Inode  fuseops.InodeID
	Offset int64
}

type cacheEntry struct {
	rd io.Reader
	t  time.Time
}

// Cache holds a list of recently read files.
type Cache struct {
	entries map[cacheKey]cacheEntry
	m       sync.Mutex
}

func newCache(ctx context.Context) *Cache {
	c := &Cache{
		entries: make(map[cacheKey]cacheEntry),
	}

	go c.cleanup(ctx)

	return c
}

// Get retrieves and removes an entry from the cache.
func (c *Cache) Get(inode fuseops.InodeID, off int64) (io.Reader, error) {
	c.m.Lock()
	defer c.m.Unlock()

	key := cacheKey{Inode: inode, Offset: off}
	entry, ok := c.entries[key]
	if !ok {
		return nil, errors.New("not found")
	}

	delete(c.entries, key)

	return entry.rd, nil
}

// Put stores an entry in the cache.
func (c *Cache) Put(inode fuseops.InodeID, off int64, rd io.Reader) {
	c.m.Lock()
	defer c.m.Unlock()

	key := cacheKey{Inode: inode, Offset: off}
	_, ok := c.entries[key]
	if ok {
		return
	}

	entry := cacheEntry{
		rd: rd,
		t:  time.Now(),
	}

	c.entries[key] = entry
}

const (
	cacheTimeout = 20 * time.Second
	cacheTicker  = 5 * time.Second
)

// cleanup removes old entries from the cache.
func (c *Cache) cleanup(ctx context.Context) {
	ticker := time.NewTicker(cacheTicker)
	defer ticker.Stop()
	for {
		select {
		case <-ticker.C:
			n := 0
			c.m.Lock()
			for key, entry := range c.entries {
				if time.Since(entry.t) > cacheTimeout {
					delete(c.entries, key)
					n++
				}
			}
			c.m.Unlock()
		case <-ctx.Done():
			return
		}
	}
}

package main

import (
	"errors"
	"fmt"
	"io"
	"io/ioutil"
	"math/rand"

	"github.com/jacobsa/fuse/fuseops"
)

const minSegmentSize = 512 * 1024      // 512KiB
const maxSegmentSize = 4 * 1024 * 1024 // 4MiB

// Segment is one segment within a file.
type Segment struct {
	Seed int64
	Size int
}

func (s Segment) String() string {
	return fmt.Sprintf("<Segment seed 0x%x, len %v>", s.Seed, s.Size)
}

type randReader struct {
	rnd *rand.Rand
	buf []byte
}

type dumpReader struct {
	rd io.Reader
}

func (d dumpReader) Read(p []byte) (int, error) {
	n, err := d.rd.Read(p)
	return n, err
}

func newRandReader(rnd *rand.Rand) io.Reader {
	return &randReader{rnd: rnd, buf: make([]byte, 0, 7)}
}

func (rd *randReader) read(p []byte) (n int, err error) {
	if len(p)%7 != 0 {
		panic("invalid buffer length, not multiple of 7")
	}

	rnd := rd.rnd
	for i := 0; i < len(p); i += 7 {
		val := rnd.Int63()

		p[i+0] = byte(val >> 0)
		p[i+1] = byte(val >> 8)
		p[i+2] = byte(val >> 16)
		p[i+3] = byte(val >> 24)
		p[i+4] = byte(val >> 32)
		p[i+5] = byte(val >> 40)
		p[i+6] = byte(val >> 48)
	}

	return len(p), nil
}

func (rd *randReader) Read(p []byte) (int, error) {
	// first, copy buffer to p
	pos := copy(p, rd.buf)
	copy(rd.buf, rd.buf[pos:])

	// shorten buf and p accordingly
	rd.buf = rd.buf[:len(rd.buf)-pos]
	p = p[pos:]

	// if this is enough to fill p, return
	if len(p) == 0 {
		return pos, nil
	}

	// load multiple of 7 byte
	l := (len(p) / 7) * 7
	n, err := rd.read(p[:l])
	pos += n
	if err != nil {
		return pos, err
	}
	p = p[n:]

	// load 7 byte to temp buffer
	rd.buf = rd.buf[:7]
	n, err = rd.read(rd.buf)
	if err != nil {
		return pos, err
	}

	// copy the remaining bytes from the buffer to p
	n = copy(p, rd.buf)
	pos += n

	// save the remaining bytes in rd.buf
	n = copy(rd.buf, rd.buf[n:])
	rd.buf = rd.buf[:n]

	return pos, nil
}

// Reader returns a reader for this segment.
func (s Segment) Reader() io.Reader {
	return io.LimitReader(newRandReader(rand.New(rand.NewSource(s.Seed))), int64(s.Size))
}

// File represents fake data with a specific seed.
type File struct {
	Seed     int64
	Size     int
	Inode    fuseops.InodeID
	Segments []Segment

	pos int64
}

func (f File) String() string {
	return fmt.Sprintf("<File seed 0x%x, Size %d>", f.Seed, f.Size)
}

// NewFile initializes a new file with the given seed.
func NewFile(seed int64, size int, inode fuseops.InodeID) *File {
	f := &File{
		Seed:  seed,
		Inode: inode,
	}

	src := rand.New(rand.NewSource(seed))
	var segmentIndex int64
	for f.Size < size {
		nextSize := size - f.Size
		if nextSize > minSegmentSize {
			max := nextSize - minSegmentSize
			if max > maxSegmentSize {
				max = maxSegmentSize
			}
			nextSize = src.Intn(max) + minSegmentSize
		}

		segment := Segment{
			Seed: seed ^ segmentIndex,
			Size: nextSize,
		}
		f.Segments = append(f.Segments, segment)

		f.Size += nextSize
		segmentIndex++
	}

	return f
}

// ReadAll returns the content of the file.
func (f File) ReadAll() ([]byte, error) {
	buf := make([]byte, f.Size)
	pos := 0
	for _, seg := range f.Segments {
		n, err := io.ReadFull(seg.Reader(), buf[pos:pos+seg.Size])
		pos += n
		if err != nil {
			return buf[:pos], err
		}
	}

	if pos != f.Size {
		return buf, io.ErrUnexpectedEOF
	}

	return buf, nil
}

// ReadAt reads the content at the offset.
func (f File) ReadAt(p []byte, off int64) (n int, err error) {
	if off < 0 {
		return 0, errors.New("not implemented")
	}

	if off > int64(f.Size) {
		return 0, errors.New("offset beyond end of file")
	}

	pos := 0
	for _, seg := range f.Segments {
		if off > int64(seg.Size) {
			off -= int64(seg.Size)
			continue
		}

		maxRead := pos + seg.Size - int(off)
		if maxRead > len(p) {
			maxRead = len(p)
		}

		rd := seg.Reader()
		if off > 0 {
			_, err = io.CopyN(ioutil.Discard, rd, off)
			if err != nil {
				return 0, err
			}

			off = 0
		}

		n, err := io.ReadFull(rd, p[pos:maxRead])
		pos += n
		if err != nil {
			return pos, err
		}

		if pos == len(p) {
			break
		}
	}

	return pos, nil
}

// Seek to the given position.
func (f *File) Seek(offset int64, whence int) (int64, error) {
	pos := f.pos
	switch whence {
	case 0:
		pos = offset
	case 1:
		pos += offset
	case 2:
		pos = int64(f.Size) - offset
	}
	if pos < 0 {
		return 0, errors.New("invalid negative position in file")
	}

	f.pos = pos

	return pos, nil
}

type contFileReader struct {
	Segments []Segment
	seg      int
	size     int
	skip     int64
	cur      io.Reader
}

// ContinuousFileReader returns a reader that yields the content of a file
// starting at start.
func ContinuousFileReader(f *File, start int64) io.Reader {
	return &contFileReader{Segments: f.Segments, skip: start, size: f.Size}
}

func (rd *contFileReader) Read(p []byte) (int, error) {

	if rd.skip > int64(rd.size) {
		return 0, errors.New("offset beyond end of file")
	}

	// skip whole segments
	if rd.skip > 0 {
		for i, s := range rd.Segments {

			if rd.skip < int64(s.Size) {
				rd.seg = i
				break
			}

			rd.skip -= int64(s.Size)
		}
	}

	if rd.seg == len(rd.Segments) {
		return 0, io.EOF
	}

	// skip bytes of current reader
	if rd.cur == nil {
		seg := rd.Segments[rd.seg]
		rd.cur = seg.Reader()

		if rd.skip > 0 {
			_, err := io.CopyN(ioutil.Discard, rd.cur, rd.skip)
			if err != nil {
				return 0, err
			}

			rd.skip = 0
		}
	}

	// read data
	pos := 0
	for pos < len(p) {
		n, err := io.ReadFull(rd.cur, p[pos:])
		pos += n

		if err == io.ErrUnexpectedEOF {
			rd.seg++
			if rd.seg >= len(rd.Segments) {
				rd.cur = nil
				return pos, io.EOF
			}

			rd.cur = rd.Segments[rd.seg].Reader()
			continue
		}

		if err != nil {
			return n, err
		}
	}

	return pos, nil
}

package main

import (
	"io"
	"os"
	"time"

	"github.com/jacobsa/fuse"
	"github.com/jacobsa/fuse/fuseops"
	"github.com/jacobsa/fuse/fuseutil"
	"golang.org/x/net/context"
)

// Entry is an entry for a file or dir in the file system.
type Entry struct {
	Attr fuseops.InodeAttributes
	Dir  *Dir
	File *File
}

// FakeDataFS is a filesystem filled with fake data.
type FakeDataFS struct {
	Seed        int64
	MaxSize     int
	FilesPerDir int

	entries map[fuseops.InodeID]Entry
	cache   *Cache

	fuseutil.NotImplementedFileSystem
}

// NewFakeDataFS creates a new filesystem.
func NewFakeDataFS(ctx context.Context, seed int64, maxSize int, filesPerDir int) (fs *FakeDataFS, err error) {
	fs = &FakeDataFS{
		Seed:        seed,
		MaxSize:     maxSize,
		FilesPerDir: filesPerDir,
		cache:       newCache(ctx),
		entries:     make(map[fuseops.InodeID]Entry),
	}
	V("create filesystem with seed %v, max size %v, %v files per dir\n", seed, maxSize, filesPerDir)

	d, err := NewDir(fs, seed, "/", filesPerDir, maxSize), nil
	if err != nil {
		return nil, err
	}

	fs.entries[fuseops.RootInodeID] = Entry{
		Dir: d,
		Attr: fuseops.InodeAttributes{
			Atime:  time.Now(),
			Ctime:  time.Now(),
			Mtime:  time.Now(),
			Crtime: time.Now(),

			Uid: uint32(os.Getuid()),
			Gid: uint32(os.Getgid()),

			Mode: os.ModeDir | 0555,
		},
	}

	return fs, nil
}

var rootAttributes = fuseops.InodeAttributes{
	Atime:  time.Now(),
	Ctime:  time.Now(),
	Mtime:  time.Now(),
	Crtime: time.Now(),

	Uid: uint32(os.Getuid()),
	Gid: uint32(os.Getgid()),

	Mode: os.ModeDir | 0555,
}

// GetInodeAttributes returns information about an inode.
func (f *FakeDataFS) GetInodeAttributes(ctx context.Context, op *fuseops.GetInodeAttributesOp) error {
	entry, ok := f.entries[op.Inode]
	if !ok {
		return fuse.ENOENT
	}

	op.Attributes = entry.Attr
	return nil
}

// OpenDir opens a directory.
func (f *FakeDataFS) OpenDir(ctx context.Context, op *fuseops.OpenDirOp) error {
	return nil
}

// ReleaseDirHandle frees a handle returned by OpenDir.
func (f *FakeDataFS) ReleaseDirHandle(context.Context, *fuseops.ReleaseDirHandleOp) error {
	return nil
}

// ForgetInode frees an inode.
func (f *FakeDataFS) ForgetInode(context.Context, *fuseops.ForgetInodeOp) error {
	return nil
}

// ReadDir lists a directory.
func (f *FakeDataFS) ReadDir(ctx context.Context, op *fuseops.ReadDirOp) error {
	entry, ok := f.entries[op.Inode]
	if !ok {
		return fuse.ENOENT
	}

	if entry.Dir == nil {
		return fuse.EIO
	}

	if int(op.Offset) > len(entry.Dir.entries) {
		return fuse.EIO
	}

	op.BytesRead = entry.Dir.ReadDir(op.Dst, int(op.Offset))
	return nil
}

