import (
	"crypto/sha1"

	"github.com/jacobsa/fuse/fuseops"
)

// inodePath returns a deterministic 32bit inode for the path p.
func inodePath(p string) fuseops.InodeID {
	var inode uint64
	hash := sha1.Sum([]byte(p))
	for i := 0; i < 4; i++ {
		shift := uint(i) * 8
		inode |= uint64(hash[i]) << shift
	}

	return fuseops.InodeID(inode)
}

package main

import (
	"crypto/sha1"
	"fmt"
	"math/rand"
	"path"

	"github.com/jacobsa/fuse/fuseops"
	"github.com/jacobsa/fuse/fuseutil"
)

// seedForPath returns a new seed for an item of typ at path.
func seedForPath(parentSeed int64, tpe string, path string) (seed int64) {
	s := fmt.Sprintf("seed-%16x/%s/%s", seed, tpe, path)
	hash := sha1.Sum([]byte(s))
	for i := 0; i < 8; i++ {
		shift := uint(i) * 8
		seed |= int64(hash[i]) << shift
	}

	return seed
}

// Dir is a directory containing fake data.
type Dir struct {
	seed    int64
	path    string
	maxSize int

	entries []fuseutil.Dirent
	// inodes  map[fuseops.InodeID]string
}

// NewDir initializes a directory.
func NewDir(fs *FakeDataFS, seed int64, dir string, numEntries, maxSize int) *Dir {
	d := Dir{
		seed:    seed,
		path:    dir,
		maxSize: maxSize,
		entries: make([]fuseutil.Dirent, numEntries),
		// inodes:  make(map[fuseops.InodeID]string),
	}

	V("generate dir %v with %d entries\n", d, numEntries)
	rnd := rand.New(rand.NewSource(d.seed))
	for i := range d.entries {
		name := fmt.Sprintf("file-%d", rnd.Int())
		inode := inodePath(path.Join(d.path, name))

		d.entries[i] = fuseutil.Dirent{
			Offset: fuseops.DirOffset(i + 1),
			Name:   name,
			Type:   fuseutil.DT_File,
			Inode:  inode,
		}

		p := path.Join(d.path, name)
		fileSeed := seedForPath(d.seed, "file", p)
		size := rnd.Intn(d.maxSize)
		f := NewFile(fileSeed, size, inodePath(p))

		fs.entries[inode] = Entry{
			File: f,
			Attr: fuseops.InodeAttributes{
				Nlink: 1,
				Mode:  0644,
				Size:  uint64(size),
			},
		}
	}

	return &d
}

func (d Dir) String() string {
	return fmt.Sprintf("<Dir %v [seed %v]>", d.path, d.seed)
}

// inode returns the inode for a given file name.
func (d Dir) inode(name string) fuseops.InodeID {
	return inodePath(path.Join(d.path, name))
}

// ReadDir returns the entries of this directory.
func (d Dir) ReadDir(dst []byte, offset int) (n int) {
	for _, entry := range d.entries[offset:] {
		written := fuseutil.WriteDirent(dst[n:], entry)
		if written == 0 {
			break
		}

		n += written
	}

	return n
}

package main

import (
	"fmt"
	"log"
	"os"
	"os/signal"
	"runtime"
	"sync"
	"syscall"

	"golang.org/x/net/context"

	"github.com/jacobsa/fuse"
	"github.com/jacobsa/fuse/fuseutil"
	"github.com/jessevdk/go-flags"
)

var (
	version = "compiled manually"
)

// Options are global settings.
type Options struct {
	Version bool `long:"version" short:"V"     description:"print version number"`
	Verbose bool `long:"verbose" short:"v"     description:"be verbose"`
	Debug   bool `long:"debug"                 description:"output debug messages"`

	Seed     int64 `long:"seed"                    default:"23" description:"initial random seed"`
	NumFiles int   `long:"files-per-dir" short:"n" default:"100" description:"number of files per directory"`
	MaxSize  int   `long:"maxsize"       short:"m" default:"100" description:"max individual file size, in KiB"`

	mountpoint string
}

var opts = Options{}
var parser = flags.NewParser(&opts, flags.HelpFlag|flags.PassDoubleDash)

var ctx context.Context

func init() {
	parser.Usage = "mountpoint"

	var cancel context.CancelFunc
	ctx, cancel = context.WithCancel(context.Background())

	c := make(chan os.Signal)
	signal.Notify(c, syscall.SIGINT)

	go func() {
		once := &sync.Once{}

		for range c {
			once.Do(func() {
				fmt.Println("Interrupt received, cleaning up")
				cancel()
			})
		}
	}()
}

// V prints debug messages if verbose mode is requested.
func V(format string, data ...interface{}) {
	if opts.Verbose {
		fmt.Printf(format, data...)
	}
}

// M prints a message to stdout.
func M(format string, data ...interface{}) {
	fmt.Printf(format, data...)
}

func mount(opts Options) (*fuse.MountedFileSystem, error) {
	fakefs, err := NewFakeDataFS(ctx, opts.Seed, opts.MaxSize*1024, opts.NumFiles)
	if err != nil {
		return nil, err
	}

	cfg := &fuse.MountConfig{
		FSName:      "fakedatafs",
		ReadOnly:    true,
		ErrorLogger: log.New(os.Stderr, "ERROR: ", log.LstdFlags),
	}

	if opts.Debug {
		cfg.DebugLogger = log.New(os.Stderr, "DEBUG: ", log.LstdFlags)
	}

	fs, err := fuse.Mount(
		opts.mountpoint,
		fuseutil.NewFileSystemServer(fakefs),
		cfg,
	)
	if err != nil {
		return nil, err
	}

	M("filesystem mounted at %v\n", opts.mountpoint)
	return fs, nil
}

func main() {
	args, err := parser.Parse()
	if e, ok := err.(*flags.Error); ok && e.Type == flags.ErrHelp {
		parser.WriteHelp(os.Stdout)
		os.Exit(0)
	}

	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
	}

	if err != nil {
		os.Exit(1)
	}

	if opts.Version {
		fmt.Printf("version %v using %v on %v/%v\n",
			version, runtime.Version(), runtime.GOOS, runtime.GOARCH)
		return
	}

	if len(args) == 0 {
		parser.WriteHelp(os.Stderr)
		os.Exit(1)
	}

	opts.mountpoint = args[0]
	fs, err := mount(opts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(2)
	}

	fs.Join(ctx)

	err = fuse.Unmount(fs.Dir())
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(3)
	}
}
